"""Incorpora la segunda revisión editorial. Datos contrastados a 17-10-2026; ejecución idempotente."""
import json
from pathlib import Path
import importlib.util

ROOT = Path(__file__).resolve().parents[1]/'investigacion'/'presidencias-centrales'
DATE='2026-10-17'
def read(name): return json.loads((ROOT/name).read_text(encoding='utf-8-sig'))
def write(name,data): (ROOT/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
eventfile=read('eventos.json');sourcefile=read('fuentes.json')
events={e['id']:e for e in eventfile['events']};sources={s['id']:s for s in sourcefile['sources']}
spec=importlib.util.spec_from_file_location('normas',Path(__file__).with_name('importar-normativa-presidencias.py'))
module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)

def source(key,url,title,kind='secondary',limit='Fuente periodística identificada. Describe el hito y la situación conocida en esa fecha; no acredita por sí sola el estado judicial posterior.'):
 sources[key]={'id':key,'url':url,'title':title,'kind':kind,'supports':title,'limits':limit,'consultedAt':DATE}
 return key

def add(day,slug,title,summary,source_id,category='crisis',stage=None,case=None,status=None,attribution=None,related=None,topics=None,display=None):
 identity=day+'-'+slug
 e={'id':identity,'date':day,'datePrecision':{10:'day',7:'month',4:'year'}[len(day)],
 'stage':stage or module.stage_for(day+'-01' if len(day)==7 else day),
 'title':title,'category':category,'summary':summary,
 'attribution':attribution or 'Acontecimiento del periodo. La inclusión documenta su relevancia pública y no implica responsabilidad penal del presidente ni valoración automática de todas las decisiones adoptadas.',
 'sources':[source_id],'pending':[],'verification':'hecho-base-documentado','reviewedAt':DATE,
 'topics':topics or (['corrupcion-y-crisis-politica','justicia-y-derechos'] if case else module.topics_for(title+' '+summary))}
 if case:e['caseId']=case
 if status:e.update(judicialStatus=status,statusAtSource=day)
 if related:e['relatedStages']=related
 if display:e['displayStages']=display
 events[identity]=e

